use std::slice;
const MAX_COUNT:usize=64;
fn lower(c:i64)->i64{if (65..=90).contains(&c){c+32}else{c}}
fn less(v:&[i64],o:&[usize;64],l:&[usize;64],p:&[usize;64],a:usize,b:usize)->bool{for i in 0..p[a].min(p[b]){let(x,y)=(lower(v[o[a]+i]),lower(v[o[b]+i]));if x!=y{return x<y;}}if p[a]!=p[b]{return p[a]<p[b];}let(sa,sb)=(l[a]-p[a],l[b]-p[b]);if sa==0||sb==0{return sa<sb;}let(mut za,mut zb)=(0,0);while za<sa&&v[o[a]+p[a]+za]==48{za+=1;}while zb<sb&&v[o[b]+p[b]+zb]==48{zb+=1;}let(na,nb)=(sa-za,sb-zb);if na!=nb{return na<nb;}for i in 0..na{let(x,y)=(v[o[a]+p[a]+za+i],v[o[b]+p[b]+zb+i]);if x!=y{return x<y;}}false}
#[no_mangle]
pub unsafe extern "C" fn natural_sort(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<1||n>4161{return -1;}let v=slice::from_raw_parts(v,n);if !(0..=64).contains(&v[0]){return -1;}let count=v[0] as usize;let(mut offs,mut lens,mut pres,mut order)=([0;64],[0;64],[0;64],[0;64]);let(mut cursor,mut total)=(1,0);for i in 0..count{if cursor>=n||!(0..=64).contains(&v[cursor]){return -1;}lens[i]=v[cursor] as usize;cursor+=1;offs[i]=cursor;pres[i]=lens[i];let mut digit=false;for j in 0..lens[i]{let c=v[cursor+j];if (48..=57).contains(&c){if j==0{return -1;}if !digit{pres[i]=j;digit=true;}}else if !((65..=90).contains(&c)||(97..=122).contains(&c))||digit{return -1;}}cursor+=lens[i];total+=lens[i];order[i]=i;}if cursor!=n{return -1;}for i in 1..count{let item=order[i];let mut j=i;while j>0&&less(v,&offs,&lens,&pres,item,order[j-1]){order[j]=order[j-1];j-=1;}order[j]=item;}let bytes=total+count.saturating_sub(1);if bytes>cap||(bytes>0&&out.is_null()){return -2;}let mut w=0;for i in 0..count{if i>0{*out.add(w)=10;w+=1;}let k=order[i];for j in 0..lens[k]{*out.add(w)=v[offs[k]+j] as u8;w+=1;}}w as i64}
